  "story-hint:Look—the toys are going into a box.": "/audio/9b910dd3dee8e3cf7874877d.mp3",
  "text:Mum is not well today.": "/audio/d44c73c935d839e8eee07aa4.mp3",
  "text:I bring her some water.": "/audio/18d87f689747770fccb22d2c.mp3",
  "story-hint:Look—the child is putting away toys.": "/audio/5855b8c681d6b331d167f63a.mp3",
  "text:“Allah, please help Mum get well.”": "/audio/c78bdf3d60a144c0bf45148e.mp3",
  "text:I sit quietly by her bed.": "/audio/5ca2db9159661d440c8ae1c1.mp3",
  "value-note:values-ready-prayer": "/audio/3d47d5177a72c207e90d1f05.mp3",
