  "text:You counted each object once.": "/audio/131d00af71eea752cb7a11fc.mp3",
  "text:The square has four equal sides.": "/audio/08fed6a36c2bbd792f9dfc9c.mp3",
  "text:You found z.": "/audio/087c200941e9c229aea0ebe3.mp3",
  "text:You shared the right amount with each place.": "/audio/cd710e8007c68a380f44cc2f.mp3",
  "text:The triangle has three sides.": "/audio/b6a4ee4cf18f579d0ab0e5a5.mp3",
