  "science-feedback:science:science-float:sort-ball": "/audio/f7dc6fe8f4dbe7a859a7c221.mp3",
  "text:The hollow plastic ball floats.": "/audio/f6e77445bd64cdfd6b5aecc5.mp3",
  "text:Did our magnet pull this steel clip?": "/audio/996487b84839a6f87d8e94c1.mp3",
  "science-hint:science:science-magnet:sort-clip": "/audio/1831be014890ee77bbb79500.mp3",
