  "science-feedback:science:science-magnet:sort-clip": "/audio/2947aa6b704fe02b3dc67d63.mp3",
  "text:Did our magnet pull this wood block?": "/audio/ee860a0eaa11dc873d2de085.mp3",
  "text:The magnet does not pull this wood block.": "/audio/9767baf2acc26b11c9af4d63.mp3",
  "science-hint:science:science-magnet:sort-wood": "/audio/260f6bd0f086bbdc1cf482cc.mp3",
  "science-feedback:science:science-magnet:sort-wood": "/audio/edd3a3e9567f46e4ff966856.mp3",
  "text:Did our magnet pull this aluminium foil?": "/audio/ddc4a6e19238828de9883077.mp3",
  "science-feedback:science:science-magnet:sort-foil": "/audio/51e42df79a68f52e5b2d282d.mp3",
  "text:The magnet does not pull this aluminium foil.": "/audio/8203fec5f2ff3e82fef9c2a2.mp3",
